{{ config(materialized='view') }}

with extracted as (
    select
        observation_id,
        venue,
        entity_id as market_id,
        batch_id,
        page_id,
        endpoint,
        observed_at,
        b.batch_loaded_at,
        source_updated_at,
        payload_hash,
        source_kind,
        json_pointer,
        json_extract_string(normalized, [
            '$.question',
            '$.slug',
            '$.description',
            '$.condition_id',
            '$.source_market_version',
            '$.protocol',
            '$.tick_size',
            '$.minimum_order_size',
            '$.volume',
            '$.liquidity',
            '$.identity_error',
            '$.membership_mode',
            '$.enclosing_event_id',
            '$.semantic_hash',
            '$.active',
            '$.closed',
            '$.archived',
            '$.resolved',
            '$.neg_risk',
            '$.enable_order_book',
            '$.accepting_orders',
            '$.usable',
            '$.tags_present',
            '$.created_at',
            '$.start_at',
            '$.end_at',
            '$.close_at',
            '$.resolved_at'
        ]) as scalar_fields,
        json_extract(normalized, [
            '$.outcomes',
            '$.raw_outcomes',
            '$.raw_clob_token_ids',
            '$.raw_position_ids',
            '$.tags',
            '$.memberships'
        ]) as json_fields
    from {{ source('bronze', 'market_observations') }} o
    join {{ ref('stg_gamma__batches') }} b using (batch_id)
)

select
    observation_id,
    venue,
    market_id,
    batch_id,
    page_id,
    endpoint,
    observed_at,
    batch_loaded_at,
    source_updated_at,
    payload_hash,
    source_kind,
    json_pointer,
    scalar_fields[1] as question,
    scalar_fields[2] as slug,
    scalar_fields[3] as description,
    scalar_fields[4] as condition_id,
    scalar_fields[5] as source_market_version,
    scalar_fields[6] as protocol,
    scalar_fields[7] as tick_size,
    scalar_fields[8] as minimum_order_size,
    scalar_fields[9] as volume,
    scalar_fields[10] as liquidity,
    scalar_fields[11] as identity_error,
    scalar_fields[12] as membership_mode,
    scalar_fields[13] as enclosing_event_id,
    scalar_fields[14] as semantic_hash,
    cast(scalar_fields[15] as boolean) as active,
    cast(scalar_fields[16] as boolean) as closed,
    cast(scalar_fields[17] as boolean) as archived,
    cast(scalar_fields[18] as boolean) as resolved,
    cast(scalar_fields[19] as boolean) as neg_risk,
    cast(scalar_fields[20] as boolean) as enable_order_book,
    cast(scalar_fields[21] as boolean) as accepting_orders,
    cast(scalar_fields[22] as boolean) as usable,
    cast(scalar_fields[23] as boolean) as tags_present,
    cast(scalar_fields[24] as timestamptz) as created_at,
    cast(scalar_fields[25] as timestamptz) as start_at,
    cast(scalar_fields[26] as timestamptz) as end_at,
    cast(scalar_fields[27] as timestamptz) as close_at,
    cast(scalar_fields[28] as timestamptz) as resolved_at,
    cast(scalar_fields[26] as timestamptz) as end_date,
    json_fields[1] as outcomes_json,
    json_fields[2] as raw_outcomes,
    json_fields[3] as raw_clob_token_ids,
    json_fields[4] as raw_position_ids,
    json_fields[5] as tags_json,
    json_fields[6] as event_refs_json
from extracted
